import generated from './media.generated.json';

/**
 * Photography manifest.
 *
 * Every image on the site resolves through this file, so the whole visual layer
 * can be re-pointed in one place. Slots are generated by `scripts/build-media.py`
 * (crop + shared grade + WebP + blur placeholder) and committed under /public/media.
 *
 * Compliance note — College of Physiotherapists of Alberta, Advertising and
 * Marketing Standard: photography must not mislead. These interim images are
 * licensed/AI-assisted illustrative scenes, not photographs of AIM patients,
 * clinicians or premises. Do not caption them as such, do not name people in
 * them, and do not attach outcome claims ("before/after", "pain-free", "expert")
 * to an image. `npm run check:copy` fails the build if an alt or caption
 * reintroduces flagged language.
 */

export type MediaAsset = {
  src: string;
  width: number;
  height: number;
  bytes: number;
  blurDataURL: string;
};

export const MEDIA = generated as Record<string, MediaAsset>;

export type MediaSlot = keyof typeof generated;

/** A resolved image ready for <SiteImage>. */
export type SlotImage = {
  slot: MediaSlot;
  alt: string;
  /** Optional short line under the image. Keep descriptive, never promotional. */
  caption?: string;
  /** Focus point for object-position, as CSS percentages. */
  position?: string;
};

/* -------------------------------------------------------------------------
 * Alt text
 * Written for a screen-reader user: what is in the frame, no claims, no names.
 * ---------------------------------------------------------------------- */

const ALT: Record<MediaSlot, string> = {
  'assess-hero': 'A physiotherapist supporting a patient through a shoulder mobility assessment in a treatment room.',
  'assess-wide': 'A physiotherapist guiding a patient through a shoulder mobility assessment beside a treatment table.',
  'assess-card': 'A physiotherapist assessing a patient’s shoulder range of motion.',
  'assess-portrait': 'A patient seated on a treatment table during a shoulder assessment.',
  'assess-detail': 'A physiotherapist supporting a patient’s arm through a guided movement.',
  'work-hero': 'A clinician reviewing a return-to-work plan with two workers on a warehouse floor.',
  'work-wide': 'A clinician and two workers in high-visibility vests reviewing a return-to-work plan on a warehouse floor.',
  'work-card': 'A worker and a clinician reviewing a return-to-work document together.',
  'work-detail': 'Close view of a return-to-work plan being reviewed on a warehouse floor.',
  'refer-hero': 'A clinician and a physician reviewing a case together on a tablet in a clinic.',
  'refer-wide': 'A clinician and a physician reviewing case notes on a tablet in a bright clinic.',
  'refer-card': 'Two health professionals reviewing case information on a tablet.',
  'refer-portrait': 'A clinician discussing a referral with a physician in a clinic.',
  'legal-wide': 'A clinical team meeting with legal counsel around a boardroom table.',
  'legal-card': 'A case review meeting between a clinical team and legal counsel.',
  'legal-portrait': 'A legal and clinical case review meeting.',
};

export function altFor(slot: MediaSlot): string {
  return ALT[slot];
}

/** Resolve a slot into the shape the image components expect. */
export function image(slot: MediaSlot, overrides: Partial<SlotImage> = {}): SlotImage {
  return { slot, alt: altFor(slot), ...overrides };
}

/* -------------------------------------------------------------------------
 * Page-type resolvers
 * One place decides which frame a page type gets, so 60+ routes stay coherent.
 * ---------------------------------------------------------------------- */

/** Program pages. `null` means no suitable frame exists yet — render the brand
 *  panel instead of an unrelated photo (see MediaPanel). */
export const PROGRAM_IMAGES: Record<string, SlotImage | null> = {
  wcb: image('work-hero'),
  mva: image('assess-hero'),
  athletic: image('assess-portrait'),
  // No age-appropriate frame in the interim library. The shoot brief lists
  // "senior balance training, clinician guarding" as priority frame #3.
  senior: null,
};

export function programImage(slug: string): SlotImage | null {
  return PROGRAM_IMAGES[slug] ?? null;
}

/** Service pages, by slug. Work-focused services borrow the workplace frame,
 *  movement-based services borrow the assessment frame. */
const WORK_SERVICES = new Set([
  'wcb-rehabilitation',
  'return-to-work',
  'work-conditioning',
  'work-hardening',
  'functional-capacity-evaluations',
]);

const REFERRAL_SERVICES = new Set<string>([]);

export function serviceImage(slug: string): SlotImage {
  if (WORK_SERVICES.has(slug)) return image('work-wide');
  if (REFERRAL_SERVICES.has(slug)) return image('refer-wide');
  return image('assess-wide');
}

/** Condition pages. Upper-body and neck presentations get the assessment frame;
 *  the rest share it too, because a second unrelated photo would be worse than
 *  a consistent one. */
export function conditionImage(_slug: string): SlotImage {
  return image('assess-card');
}

/** Location pages have no trustworthy facility photography yet. Returning null
 *  keeps us from implying a building or room that is not the one patients
 *  walk into; the location page renders its own locality treatment instead. */
export function locationImage(_slug: string): SlotImage | null {
  return null;
}

/* -------------------------------------------------------------------------
 * Band images for full-width sections
 * ---------------------------------------------------------------------- */

export const BANDS = {
  homeProof: image('work-wide'),
  homeWhy: image('assess-portrait'),
  getCare: image('refer-wide'),
  about: image('assess-wide'),
  employers: image('work-wide'),
  referrers: image('refer-wide'),
  lawyers: image('legal-wide'),
} satisfies Record<string, SlotImage>;
